import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import vm from 'node:vm';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { gunzipSync } from 'node:zlib';
import { afterEach, describe, expect, it } from 'vitest';

const root = path.resolve(__dirname, '..');
const temporaryRoots: string[] = [];
// Offline, exact published source fixtures, not a native compilation claim.
// npm tarballs: expo-live-activity@0.4.2, expo-modules-core@57.0.26,
// expo@57.0.33, expo-build-properties@57.0.23, @expo/config-plugins@57.0.13,
// expo-crypto@57.0.4, expo-template-bare-minimum@57.0.0.
// Registry metadata and deprecation were inspected separately; 0.4.2 remains
// latest stable, but upstream maintenance is discontinued. No alpha migration.
const fixtures: Record<string, string> = JSON.parse(gunzipSync(Buffer.from('', 'base64')).toString('utf8'));
const NATIVE_MODULE_SHA256 = '7c28769d0974b83df18dc765008d2fb6299dee71ff928a7c9207860e39150333';

function source(relativePath: string) {
  return fs.readFileSync(path.join(root, relativePath), 'utf8');
}
function tempProject() {
  const project = fs.mkdtempSync(path.join(os.tmpdir(), 'hy3n-sdk57-live-activity-test-'));
  temporaryRoots.push(project);
  return project;
}
function put(project: string, name: string, text: string) {
  const target = path.join(project, name);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, text);
  return target;
}
function runPatch(project: string) {
  return spawnSync(process.execPath, [path.join(project, 'scripts/patch-expo-live-activity.mjs')], {
    cwd: project, encoding: 'utf8', timeout: 10_000,
  });
}
function patchProject(cryptoConfig = fixtures['crypto/expo-module.config.json']) {
  const project = tempProject();
  put(project, 'scripts/patch-expo-live-activity.mjs', source('scripts/patch-expo-live-activity.mjs'));
  for (const [key, content] of Object.entries(fixtures)) {
    if (key.startsWith('live/')) put(project, `node_modules/expo-live-activity/${key.slice(5)}`, content);
  }
  put(project, 'node_modules/expo-crypto/package.json', fixtures['crypto/package.json']);
  put(project, 'node_modules/expo-crypto/expo-module.config.json', cryptoConfig);
  return project;
}
// Execute only the existing finalized branding callback against temporary
// Swift/plist fixtures. This is NOT Expo prebuild or native generation.
function brandingAction() {
  let action: ((mod: any) => Promise<any>) | undefined;
  const sandbox = {
    module: { exports: undefined as any },
    require: (name: string) => {
      if (name === '@expo/config-plugins') return {
        withFinalizedMod: (config: any, [platform, callback]: [string, typeof action]) => {
          expect(platform).toBe('ios'); action = callback; return config;
        },
      };
      if (name === 'fs') return fs;
      if (name === 'path') return path;
      throw new Error(`Unexpected plugin dependency ${name}`);
    },
    process: { env: { EAS_BUILD_PROFILE: 'production' } },
  };
  vm.runInNewContext(source('plugins/withHy3nLiveActivityBranding.js'), sandbox);
  sandbox.module.exports({});
  if (!action) throw new Error('Missing branding finalized callback');
  return action;
}
function brandingProject() {
  const project = tempProject();
  for (const [key, content] of Object.entries(fixtures)) {
    if (key.startsWith('live/ios-files/')) put(project, `ios/LiveActivity/${key.split('/').pop()}`, content);
  }
  const appInfo = `<?xml version="1.0"?><plist version="1.0"><dict>
<key>UIApplicationSceneManifest</key><dict><key>UISceneConfigurations</key><dict>
<key>UIWindowSceneSessionRoleApplication</key><array><dict>
<key>UISceneDelegateClassName</key><string>EXExpoAppSceneDelegate</string>
</dict></array></dict></dict>
<key>NSSupportsLiveActivitiesFrequentUpdates</key><false/>
</dict></plist>`;
  put(project, 'ios/HY3N/Info.plist', appInfo);
  put(project, 'ios/HY3N/HY3N.entitlements', '<plist><dict><key>aps-environment</key><string>development</string></dict></plist>');
  put(project, 'ios/HY3N/AppDelegate.swift', fixtures['template/ios/HelloWorld/AppDelegate.swift']);
  put(project, 'ios/HY3N.xcodeproj/project.pbxproj', '// main app and extension target ownership sentinel\n');
  return {
    project, appInfo,
    mod: { modRequest: { platformProjectRoot: path.join(project, 'ios'), projectName: 'HY3N' } },
  };
}
afterEach(() => {
  for (const directory of temporaryRoots.splice(0)) fs.rmSync(directory, { recursive: true, force: true });
});

describe('SDK57 Live Activity offline native-source compatibility', () => {
  it('pins the stable 0.4.2 source and retains Expo module registration without a legacy view manager', () => {
    const metadata = JSON.parse(fixtures['live/package.json']);
    expect(metadata.version).toBe('0.4.2');
    expect(metadata.peerDependencies).toEqual({ expo: '*', react: '*', 'react-native': '*' });
    const module = fixtures['live/ios/ExpoLiveActivityModule.swift'];
    expect(createHash('sha256').update(module).digest('hex')).toBe(NATIVE_MODULE_SHA256);
    expect(fs.readFileSync(path.join(root, 'node_modules/expo-live-activity/ios/ExpoLiveActivityModule.swift'), 'utf8')).toBe(module);
    expect(JSON.parse(fixtures['live/expo-module.config.json']).apple.modules).toEqual(['ExpoLiveActivityModule']);
    expect(module).toContain('public class ExpoLiveActivityModule: Module');
    expect(module).not.toMatch(/RCTBridgeModule|RCTViewManager|RCT_NEW_ARCH_ENABLED|UIApplication\.shared|ExpoAppSceneDelegate/);
  });

  it('uses builder, record, enumeration, event and exception APIs still exported by SDK57 core', () => {
    const module = fixtures['live/ios/ExpoLiveActivityModule.swift'];
    for (const component of ['Name("ExpoLiveActivity")', 'OnCreate {', 'Events("onTokenReceived"', 'Function("startActivity")', 'Function("updateActivity")', 'Function("stopActivity")']) {
      expect(module).toContain(component);
    }
    expect(fixtures['core/ios/Core/Modules/Module.swift']).toContain('public typealias Module = AnyModule & BaseModule');
    expect(fixtures['core/ios/Core/Modules/Module.swift']).toContain('public func sendEvent(_ eventName: String, _ body: [String: Any?]');
    expect(fixtures['core/ios/Core/Protocols/AnyModule.swift']).toContain('@ModuleDefinitionBuilder\n  func definition() -> ModuleDefinition');
    expect(fixtures['core/ios/Api/Factories/ModuleFactories.swift']).toContain('public func Name(_ name: String)');
    expect(fixtures['core/ios/Api/Factories/EventListenersFactories.swift']).toContain('public func OnCreate(');
    expect(fixtures['core/ios/Api/Factories/ObjectFactories.swift']).toContain('public func Events(_ names: String...)');
    expect(fixtures['core/ios/Api/Factories/SyncFunctionFactories.swift']).toContain('public func Function<R, A0: AnyArgument, each A: AnyArgument>');
    expect(fixtures['core/ios/Core/Records/Record.swift']).toContain('public protocol Record:');
    expect(fixtures['core/ios/Core/Records/Field.swift']).toContain('public final class Field<Type: AnyArgument>');
    expect(fixtures['core/ios/Core/Records/Field.swift']).toContain('where Type: ExpressibleByNilLiteral');
    expect(fixtures['core/ios/Core/Records/FieldExtensions.swift']).toContain('public extension Field where Type == String');
    expect(fixtures['core/ios/Core/Arguments/Enumerable.swift']).toContain('public protocol Enumerable: AnyArgument, CaseIterable');
    expect(fixtures['core/ios/Core/Exceptions/Exception.swift']).toContain('open class Exception:');
    expect(fixtures['core/ios/Core/Exceptions/GenericException.swift']).toContain('open class GenericException<ParamType: ~Copyable>: Exception');
  });

  it('retains ActivityKit OS guards, simultaneous ETA/progress and immediate terminal dismissal', () => {
    const module = fixtures['live/ios/ExpoLiveActivityModule.swift'];
    expect(module).toContain('guard #available(iOS 17.2, *), ActivityAuthorizationInfo().areActivitiesEnabled');
    for (const method of ['startActivity', 'stopActivity', 'updateActivity']) {
      const section = module.slice(module.indexOf(`Function("${method}")`));
      expect(section).toContain('guard #available(iOS 16.2, *)');
      expect(section).toContain('timerEndDateInMilliseconds: state.progressBar?.date');
      expect(section).toContain('progress: state.progressBar?.progress');
    }
    expect(module).toContain('dismissalPolicy: .immediate');
    expect(fixtures['live/plugin/src/index.ts']).toContain("const deploymentTarget = '16.2'");
    expect(fixtures['live/plugin/src/xcode/addXCConfigurationList.ts']).toContain('APPLICATION_EXTENSION_API_ONLY:');
    expect(fixtures['live/plugin/src/xcode/addXCConfigurationList.ts']).toContain('\'"YES"\'');
  });

  it('keeps unavailable scene/Expo/React code outside the WidgetKit extension', () => {
    expect(fixtures['expo/ExpoAppSceneDelegate.swift']).toContain('@available(iOSApplicationExtension, unavailable)');
    expect(fixtures['live/plugin/src/lib/getWidgetFiles.ts']).toContain("'/ios-files'");
    const buildPhases = fixtures['live/plugin/src/xcode/addBuildPhases.ts'];
    expect(buildPhases).toContain('[...swiftFiles, ...intentFiles]');
    expect(buildPhases).toContain("xcodeProject.addBuildPhase([], 'PBXFrameworksBuildPhase'");
    expect(fixtures['live/ios/ExpoLiveActivity.podspec']).toContain("s.dependency 'ExpoModulesCore'");
    for (const [key, content] of Object.entries(fixtures)) {
      if (!key.startsWith('live/ios-files/')) continue;
      expect(content, key).not.toMatch(/(?:internal\s+)?import\s+(?:Expo|ExpoModulesCore|React)\b|ExpoAppSceneDelegate|UIApplication\.shared|UIApplicationSceneManifest|ExpoLiveActivityModule/);
    }
    expect(fixtures['live/ios-files/Info.plist']).toContain('com.apple.widgetkit-extension');
    expect(fixtures['live/ios-files/LiveActivityWidgetBundle.swift']).toContain('@main\nstruct LiveActivityWidgetBundle: WidgetBundle');
  });

  it('repairs live-activity publication while preserving exact SDK57 crypto metadata and all native sources', () => {
    const project = patchProject();
    const cryptoPath = path.join(project, 'node_modules/expo-crypto/expo-module.config.json');
    const beforeCrypto = fs.readFileSync(cryptoPath, 'utf8');
    const cryptoMtime = fs.statSync(cryptoPath).mtimeMs;
    const first = runPatch(project);
    expect(first.status, first.stderr).toBe(0);
    expect(first.stdout).toContain('Repaired expo-live-activity Android publication metadata');
    const configPath = path.join(project, 'node_modules/expo-live-activity/expo-module.config.json');
    const patched = fs.readFileSync(configPath, 'utf8');
    const config = JSON.parse(patched);
    expect(config.apple).toEqual({ modules: ['ExpoLiveActivityModule'] });
    expect(config.android.publication).toEqual({ groupId: 'host.exp.exponent', artifactId: 'expo.modules.liveactivity', version: '0.4.2', repository: 'local-maven-repo' });
    const mtime = fs.statSync(configPath).mtimeMs;
    const second = runPatch(project);
    expect(second.status, second.stderr).toBe(0);
    expect(second.stdout).toBe('');
    expect(fs.readFileSync(configPath, 'utf8')).toBe(patched);
    expect(fs.statSync(configPath).mtimeMs).toBe(mtime);
    expect(fs.readFileSync(cryptoPath, 'utf8')).toBe(beforeCrypto);
    expect(fs.statSync(cryptoPath).mtimeMs).toBe(cryptoMtime);
    for (const [key, content] of Object.entries(fixtures)) {
      if (key.startsWith('live/ios')) expect(fs.readFileSync(path.join(project, 'node_modules/expo-live-activity', key.slice(5)), 'utf8')).toBe(content);
    }
  });

  it('does not overwrite already-complete custom publication values', () => {
    const publication = { groupId: 'custom.group', artifactId: 'custom.crypto', version: '57.0.4', repository: 'custom-repo' };
    const config = JSON.parse(fixtures['crypto/expo-module.config.json']);
    config.android.publication = publication;
    const project = patchProject(JSON.stringify(config));
    expect(runPatch(project).status).toBe(0);
    expect(JSON.parse(fs.readFileSync(path.join(project, 'node_modules/expo-crypto/expo-module.config.json'), 'utf8')).android.publication).toEqual(publication);
  });

  it('brands only display views, preserves main-app scenes and ownership, and is content-idempotent', async () => {
    const { project, appInfo, mod } = brandingProject();
    const action = brandingAction();
    const appDelegatePath = path.join(project, 'ios/HY3N/AppDelegate.swift');
    const xcodePath = path.join(project, 'ios/HY3N.xcodeproj/project.pbxproj');
    const delegateBefore = fs.readFileSync(appDelegatePath, 'utf8');
    const xcodeBefore = fs.readFileSync(xcodePath, 'utf8');
    const widgetInfo = fs.readFileSync(path.join(project, 'ios/LiveActivity/Info.plist'), 'utf8');
    await action(mod);
    expect(fs.readFileSync(path.join(project, 'ios/HY3N/Info.plist'), 'utf8')).toBe(appInfo.replace('<false/>', '<true/>'));
    expect(fs.readFileSync(path.join(project, 'ios/HY3N/HY3N.entitlements'), 'utf8')).toContain('<string>production</string>');
    expect(fs.readFileSync(appDelegatePath, 'utf8')).toBe(delegateBefore);
    expect(fs.readFileSync(xcodePath, 'utf8')).toBe(xcodeBefore);
    expect(fs.readFileSync(path.join(project, 'ios/LiveActivity/Info.plist'), 'utf8')).toBe(widgetInfo);
    const widgetPath = path.join(project, 'ios/LiveActivity/LiveActivityWidget.swift');
    const lockPath = path.join(project, 'ios/LiveActivity/LiveActivityView.swift');
    const widget = fs.readFileSync(widgetPath, 'utf8');
    const lock = fs.readFileSync(lockPath, 'utf8');
    expect(widget).toContain('HY3N trip-progress presentation v3');
    expect(lock).toContain('HY3N trip-progress Lock Screen presentation v3');
    expect(widget).toContain('struct LiveActivityAttributes: ActivityAttributes');
    expect(widget).toContain('context.state.timerEndDateInMilliseconds');
    expect(widget).toContain('context.state.progress ?? 0');
    for (const text of [widget, lock]) expect(text).not.toMatch(/ExpoAppSceneDelegate|UIApplication\.shared|import Expo|import React/);
    const helperPrefix = fixtures['live/ios-files/LiveActivityView.swift'].split('struct LiveActivityView: View {')[0];
    expect(lock.startsWith(helperPrefix)).toBe(true);
    await action(mod);
    expect(fs.readFileSync(widgetPath, 'utf8')).toBe(widget);
    expect(fs.readFileSync(lockPath, 'utf8')).toBe(lock);
  });

  it('fails rather than branding an unrecognized or missing extension layout', async () => {
    const first = brandingProject();
    put(first.project, 'ios/LiveActivity/LiveActivityWidget.swift', '// incompatible upstream layout\n');
    await expect(brandingAction()(first.mod)).rejects.toThrow('Could not locate the Expo Live Activity Dynamic Island layout');
    const second = brandingProject();
    fs.rmSync(path.join(second.project, 'ios/LiveActivity/LiveActivityView.swift'));
    await expect(brandingAction()(second.mod)).rejects.toThrow('extension views were not generated');
  });

  it('preserves display-only isolation and existing end-trip serialization/retry safeguards', () => {
    const integration = source('lib/rider-live-activity.ts');
    expect(integration).toContain("return Platform.OS === 'ios'");
    expect(integration).toContain('terminalRideIds.add(rideId)');
    expect(integration).toContain('if (terminalRideIds.has(ride.id)) return');
    expect(integration).toContain('await enqueueActivityOperation(rideId');
    expect(integration).toContain('scheduleLiveActivityStopRetry(activity, completed, attempt)');
    const stop = integration.slice(integration.indexOf('async function stopRiderLiveActivity('));
    expect(stop.indexOf('await stopActivity(activity.activityId')).toBeLessThan(stop.indexOf('activitiesByRideId.delete(activity.rideId)'));
    expect(source('plugins/withHy3nLiveActivityBranding.js')).toContain('no fare, wallet, or ride-state authority');
  });
});


describe('SDK57 scene/AppDelegate integration boundaries (source callbacks only)', () => {
  it('preserves Firebase initialization when the scene transform removes legacy startup', () => {
    // Firebase is a dangerous mod; Expo57 orders dangerous before appDelegate.
    // Reproduce those pure transforms without invoking a mod compiler/prebuild.
    const original = fixtures['template/ios/HelloWorld/AppDelegate.swift'];
    const firebasePlugin = source('node_modules/@react-native-firebase/app/plugin/build/ios/appDelegate.js');
    const codeSandbox = { exports: {} as any, require: (name: string) => {
      if (name === 'crypto') return { createHash };
      throw new Error(`Unexpected generateCode dependency ${name}`);
    } };
    vm.runInNewContext(fixtures['config/build/utils/generateCode.js'], codeSandbox);
    const firebaseSandbox = {
      exports: {} as any,
      require: (name: string) => {
        if (name === '@expo/config-plugins') return { WarningAggregator: { addWarningIOS: () => { throw new Error('Unexpected Firebase warning'); } } };
        if (name.endsWith('/generateCode')) return codeSandbox.exports;
        if (name === 'fs') return fs;
        throw new Error(`Unexpected Firebase dependency ${name}`);
      },
    };
    vm.runInNewContext(firebasePlugin, firebaseSandbox);
    const firebaseDelegate = firebaseSandbox.exports.modifySwiftAppDelegate(original);
    expect(firebaseDelegate).toContain('import FirebaseCore');
    expect(firebaseDelegate).toContain('FirebaseApp.configure()');
    expect(firebaseDelegate).toContain('@generated begin @react-native-firebase/app-didFinishLaunchingWithOptions');
    let update: ((mod: any) => any) | undefined;
    let plist: ((mod: any) => any) | undefined;
    const sceneSandbox = {
      exports: {} as any,
      require: (name: string) => {
        if (name === 'expo/config-plugins') return {
          withAppDelegate: (config: any, action: typeof update) => { update = action; return config; },
          withInfoPlist: (config: any, action: typeof plist) => { plist = action; return config; },
        };
        if (name === 'resolve-from') return { silent: () => undefined };
        if (name === 'semver') return { valid: (v: string) => v, major: () => 57, lt: () => false };
        throw new Error(`Unexpected scene dependency ${name}`);
      },
    };
    vm.runInNewContext(fixtures['scene/build/iosSceneSupport.js'], sceneSandbox);
    sceneSandbox.exports.withIosSceneSupport({ sdkVersion: '57.0.33' }, { ios: { enableSceneSupport: true } });
    if (!update || !plist) throw new Error('Missing scene source callbacks');
    const sceneDelegate = update({ modResults: { language: 'swift', contents: firebaseDelegate } }).modResults.contents;
    expect(sceneDelegate).toContain('class AppDelegate: ExpoAppDelegate, ExpoReactNativeFactoryProvider {');
    expect(sceneDelegate).toContain('FirebaseApp.configure()');
    expect(sceneDelegate).toContain('import FirebaseCore');
    expect(sceneDelegate).not.toContain('factory.startReactNative(');
    expect(sceneDelegate).not.toContain('window = UIWindow(frame:');
    expect(sceneDelegate).toContain('return super.application(application, didFinishLaunchingWithOptions: launchOptions)');
    expect(update({ modResults: { language: 'swift', contents: sceneDelegate } }).modResults.contents).toBe(sceneDelegate);
    expect(plist({ modResults: {} }).modResults.UIApplicationSceneManifest.UISceneConfigurations.UIWindowSceneSessionRoleApplication[0].UISceneDelegateClassName).toBe('EXExpoAppSceneDelegate');
    expect(fixtures['config/build/plugins/mod-compiler.js']).toContain('dangerous: -2');
    expect(fixtures['config/build/plugins/mod-compiler.js']).toContain('finalized: 1');
    expect(source('node_modules/@react-native-firebase/app/plugin/src/ios/appDelegate.ts')).toContain('return withDangerousMod(config');
    expect(source('node_modules/@react-native-firebase/messaging/plugin/src/index.ts')).not.toContain('withAppDelegate');
  });

  it('keeps modular headers scoped to Google pods, never globally modularizing React', () => {
    const plugin = source('plugins/withPodfileModularHeaders.js');
    expect(plugin).toContain("pod 'GoogleUtilities', :modular_headers => true");
    expect(plugin).toContain("pod 'RecaptchaInterop', :modular_headers => true");
    expect(plugin).not.toMatch(/^\s*use_modular_headers!/m);
    expect(plugin).not.toMatch(/pod ['"]React[^'"\n]*['"]/);
  });
});
